  summary, body, image_url, image_credit, image_source, verification_json, source
) VALUES (
  'mapleton-pumping-station-outage-cuts-tshwane-water-2026-11-03',
  'Power failure at Rand Water''s Mapleton plant cuts Tshwane supply',
  'Utilities', '2026-11-03', 'EWN', 'https://www.ewn.co.za/2026/11/03/water-off-in-parts-of-ekurhuleni-and-tshwane',
  'A power failure at Rand Water''s Mapleton pumping station on 2 November halted pumping to Tshwane and five other municipalities, with recovery expected to take days.',
  'An electricity fault in the City of Ekurhuleni''s network knocked out power to Rand Water''s Mapleton pumping station on the night of Monday, 2 November, stopping it from pumping into the shared bulk water system. Rand Water said the breakdown threatened supply to six municipalities, with Tshwane and Ekurhuleni the hardest hit, while Lesedi, Govan Mbeki, Thembisile Hani and Victor Khanye further east also faced reduced pressure.

Power to the station was restored on Tuesday, 3 November, and Rand Water resumed pumping, though spokesperson Makanosi Maroo said the plant was running at roughly half its normal output while the network recovered. Ekurhuleni spokesperson Zweli Dlamini said customer supply would return gradually, starting with low-lying areas, because reservoir and pipe levels had already dropped during the outage. Rand Water, which has also pointed to persistently high water use in the region as an added strain on the system, asked residents to cut back on consumption while pumping returns to normal.',
  NULL, NULL, NULL,
  '["https://www.ewn.co.za/2026/11/03/water-off-in-parts-of-ekurhuleni-and-tshwane", "https://www.timeslive.co.za/news/south-africa/2026-11-03-six-municipalities-face-gradual-water-recovery-after-mapleton-pumping-station-outage/"]',
  'agent'
);
INSERT OR IGNORE INTO news (
  slug, title, category, published_date, source_name, source_url,
  summary, body, image_url, image_credit, image_source, verification_json, source
) VALUES (
  'markgraaff-wins-sas-first-youth-olympics-medal-2026-11-02',
  'Tuks swimmer wins South Africa''s first medal at Youth Olympics',
  'Sport', '2026-11-02', 'EWN', 'https://www.ewn.co.za/2026/11/02/leah-markgraaff-strikes-silver-to-open-team-sas-medal-tally-at-2026-youth-olympic-games',
  'TuksSport swimmer Leah Markgraaff, 17, won silver in the 400m freestyle in Dakar, giving Team South Africa its first medal of the 2026 Youth Olympic Games.',
  'Leah Markgraaff, a 17-year-old who swims for TuksSport at the University of Pretoria, won silver in the girls'' 400m freestyle on Sunday in Senegal''s capital, Dakar, opening Team South Africa''s medal tally at this year''s Youth Olympics. She touched the wall in 4:26.13 at the open-air Dakar Aquatic Centre, finishing behind Ecuador''s Elvira Espinosa, who took gold in 4:22.87, with Belgium''s Celya Paques taking bronze.

Markgraaff set the early pace and led for the first two laps, slipped to third by halfway, then pushed past Bulgaria''s Simona Ivanova after the 250m mark to move into second. It was the ninth swimming medal South Africa has won across four Youth Olympic Games since 2010, and followed a strong 2025 showing for Markgraaff, who claimed three golds at the Africa Youth Games in Angola''s capital, Luanda. She said the result had not yet sunk in, calling it a good achievement, and was due to race again in the 100m freestyle.',
  NULL, NULL, NULL,
  '["https://www.ewn.co.za/2026/11/02/leah-markgraaff-strikes-silver-to-open-team-sas-medal-tally-at-2026-youth-olympic-games", "https://superschoolsnews.co.za/leah-markgraaff-wins-team-sas-first-medal-at-the-2026-youth-olympic-games/", "https://www.timeout.com/pretoria/news/team-south-africa-racks-up-youth-olympic-games-medals-in-dakar-110526"]',
  'agent'
);
